"""Lesson 10: existing narrated assembly plus graphs generated by executed Python."""
import json,os,re,hashlib,subprocess
from pathlib import Path
from PIL import Image,ImageDraw
import build_lesson02 as e
ROOT=e.ROOT
e.WORK=ROOT.parent/'production/lesson10';e.OUT=e.SITE/'videos/lesson10'
e.WORK.mkdir(parents=True,exist_ok=True);e.OUT.mkdir(parents=True,exist_ok=True)
e.scenes=json.loads(Path(__file__).with_name('lesson10-scenes.json').read_text())
def run_program(s):
 code=s.get('runCode',s['code']);data=(e.SITE/'datasets/school_store_fictional.csv').read_bytes()
 folder=e.WORK/'runs'/hashlib.sha256(code.encode()+data).hexdigest()[:20];folder.mkdir(parents=True,exist_ok=True)
 marker=folder/'execution.json'
 if not marker.exists():
  (folder/'school_store_fictional.csv').write_bytes(data)
  # Capture the figure before show, without changing any plotted data or styling.
  capture="\nimport matplotlib.pyplot as _plt\nfor _n in _plt.get_fignums():\n    _plt.figure(_n).savefig('verified_graph.png', dpi=180, bbox_inches='tight')\n"
  source=code.replace('plt.show()',capture+'\nplt.show()')
  if 'plt.show()' not in code:source+=capture
  (folder/'lesson10.py').write_text(source)
  r=subprocess.run(['python3','lesson10.py'],cwd=folder,env={**os.environ,'MPLBACKEND':'Agg'},capture_output=True,text=True)
  expected=s.get('expectError')
  if expected:assert r.returncode!=0 and expected in r.stderr,(s['title'],r.stderr)
  else:assert r.returncode==0,(s['title'],r.stderr)
  output=r.stdout.rstrip()
  if r.returncode:output=r.stderr.strip().splitlines()[-1]
  marker.write_text(json.dumps({'stdout':output,'returncode':r.returncode,'expectedError':expected,'codeSha256':hashlib.sha256(code.encode()).hexdigest()},ensure_ascii=False,indent=2)+'\n')
 return json.loads(marker.read_text())['stdout'],folder

def visual(s):
 result=run_program(s)[0] if s['kind'] in ['code','graph'] else ''
 if s['kind']=='question':result='먼저 정답과 근거를 적으세요.'
 if s['kind']=='answer':result='평균 20.0개 / 최댓값 30개\nbread 30개\n연간 경향 확정 불가\n매출과 이익 구별\n관찰과 원인 추측 구별'
 return s['code'],result,s['note']
e.visual=visual

def frame(s,idx,total,code,output,note,shown,active,progress):
 im=Image.new('RGB',(1920,1080),'#f1f6fa');d=ImageDraw.Draw(im)
 d.rectangle((0,0,1920,126),fill='#102c3c');d.text((48,20),'10차시 · 분석 보고서·기말 종합',font=e.font(43),fill='white')
 d.text((50,80),'영수쌤의 Python 교실 · 소프트웨어와 생활',font=e.font(25),fill='#a9d9d0')
 d.text((48,149),f'{idx+1:02} / {total:02}   '+s['title'],font=e.font(32),fill='#173c4d')
 d.rounded_rectangle((40,210,1110,884),radius=16,fill='#102633')
 label={'guide':'실습 순서','question':'결과 예측 문제','answer':'정답과 해설'}.get(s['kind'],'Python 코드')
 d.text((64,228),label,font=e.font(25),fill='#a6d8d1')
 for n,line in enumerate(code.splitlines()[:16]):
  y=280+n*35
  if n==active:d.rounded_rectangle((54,y-2,1096,y+34),radius=5,fill='#285367')
  d.text((63,y),f'{n+1:2}',font=e.font(24,True),fill='#7998a9')
  d.text((113,y),line if n<shown or s['kind']!='code' else '',font=e.font(27,not bool(re.search('[가-힣]',line))),fill='#edf7f8')
 graph=None
 if s.get('chart'):
  _,folder=run_program(s);graph=folder/'verified_graph.png';assert graph.exists()
 if graph and progress>.43:
  with Image.open(graph) as chart:
   chart=chart.convert('RGB');chart.thumbnail((730,650));d.rounded_rectangle((1132,210,1880,884),radius=16,fill='white');im.paste(chart,(1141+(730-chart.width)//2,222+(650-chart.height)//2))
 else:
  d.rounded_rectangle((1132,210,1880,438),radius=16,fill='white',outline='#d6e2e9',width=2)
  label='수업용 가상 하루 · 세 상품'
  rows=[['상품','판매량 (개)'],['juice','42' if s.get('dataset')=='changed' else '12'],['bread','30'],['milk','18']]
  if s.get('dataset')=='sorted':rows=[['상품','판매량 (개)'],['bread','30'],['milk','18'],['juice','12']]
  if s.get('dataset')=='csv':label='확장 CSV · 가상의 월~금';rows=[['구조','확인'],['데이터','10행·5열'],['판매량','sold · 개'],['가격','price · 원'],['비 표시','rain · 0 또는 1']]
  if s.get('dataset')=='summary':label='확장 CSV · 월~금 상품별 합계';rows=[['상품','판매량(개)','매출(원)'],['김밥','131','458500'],['주스','86','172000']]
  if s.get('dataset')=='means':label='확장 CSV · 상품별 요일 평균';rows=[['대상','평균 판매량(개)'],['전체 10행','21.7'],['김밥 5행','26.2'],['주스 5행','17.2']]
  if s.get('dataset')=='rain':label='하루 전체 판매량의 평균 비교';rows=[['비 여부','기록 일수','평균(개)'],['없음(0)','3','50.0'],['있음(1)','2','33.5']]
  d.text((1156,227),label,font=e.font(24),fill='#173c4d')
  rh=27
  for j,row in enumerate(rows):
   for c,value in enumerate(row):
    w=718//len(row);x=1150+c*w;y=268+j*rh;d.rectangle((x,y,x+w-9,y+rh-3),fill='#e5f4f1' if j==0 else '#f3f7fa');d.text((x+10,y+1),value,font=e.font(23),fill='#123b46')
  d.rounded_rectangle((1132,456,1880,884),radius=16,fill='#102633')
  d.text((1156,474),'실행 결과' if s['kind']=='code' else '확인할 내용',font=e.font(25),fill='#a6d8d1')
  result=output if progress>.43 or s['kind']!='code' else '실행 전에 결과를 예측하세요.'
  if not result:result='아직 print 출력은 없습니다.' if s['kind']=='code' else note
  lines=[]
  for paragraph in result.split('\n'):lines.extend(e.wrap(paragraph,23,694,not bool(re.search('[가-힣]',paragraph))))
  assert len(lines)<=10,(s['title'],'output overflow')
  for n,line in enumerate(lines):d.text((1156,524+n*32),line,font=e.font(23,not bool(re.search('[가-힣]',line))),fill='#e5fbe8')
 if s['kind']=='graph':
  with Image.open(graph) as chart:
   chart=chart.convert('RGB');chart.thumbnail((1810,674));d.rectangle((40,210,1880,884),fill='white');im.paste(chart,((1920-chart.width)//2,210+(674-chart.height)//2))
 d.rectangle((0,908,1920,1080),fill='#071b26')
 for n,line in enumerate(e.wrap(note,25,1816)[:2]):d.text((48,916+n*32),line,font=e.font(25),fill='#f5cc78')
 d.rectangle((0,1072,int(1920*progress),1080),fill='#36c5b5')
 return im

e.frame=frame
if __name__=='__main__':e.build()
